/// `EmotionChip.after_damage_received` — accumulate HP loss into the
/// per-instance counter so the next player turn-start can detect "took
/// HP loss last turn". Mirrors Python `EmotionChip._took_damage` flag,
/// but tracked as an i32 sum (presence of any positive damage is what
/// matters at consume-time).
pub(crate) fn on_after_damage_received_emotion_chip(
    state: &mut CombatState,
    ctx: &crate::hooks::DamageCtx,
    damage: i32,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::EmotionChip) {
        return EffectResult::NotImplemented;
    }
    if !matches!(ctx.target, crate::hooks::CreatureRef::Player) {
        return EffectResult::NotImplemented;
    }
    if damage <= 0 {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = state
        .relics
        .iter_mut()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip)
    {
        r.counter = r.counter.saturating_add(damage);
    }
    EffectResult::Resolved
}

/// `EmotionChip.after_side_turn_start` — on player turn start, if the
